<?php
declare(strict_types=1);
require dirname(__DIR__,2).'/app/bootstrap.php';
use Kios\Infrastructure\{Database,StaffAccountService};
use Kios\MerchantOperations\{StaffSessionIdentity,OperationalAnalytics,Inventory};
use Kios\MerchantFoundation\Identity;
$db=Database::connect();$meta=json_decode(file_get_contents($argv[1]),true);$creds=json_decode(file_get_contents($argv[2]),true);$a=$meta['merchants']['a'];$b=$meta['merchants']['b'];$r=['passed'=>0,'failed'=>0,'cases'=>[]];
function ok(bool $v):void{if(!$v)throw new RuntimeException('Assertion failed');}
function test(string $n,callable $f):void{global $r;try{$f();$r['passed']++;$r['cases'][$n]='PASS';}catch(Throwable $e){$r['failed']++;$r['cases'][$n]=get_class($e).':'.$e->getMessage();}}
function deny(callable $f):void{try{$f();}catch(DomainException|InvalidArgumentException){return;}throw new RuntimeException('Expected authorization/validation denial');}
function auth(array $m,string $user,string $password):StaffSessionIdentity{global $db;$q=$db->prepare('SELECT outlet_code FROM outlets WHERE outlet_id=?');$q->execute([$m['loginOutlet']]);$native=(new StaffAccountService($db,$q->fetchColumn(),getenv('KIOS_MERCHANT_AUTH_RATE_KEY')))->authenticate($user,$password,'m05d-synthetic');ok($native!==null);$s=[];StaffAccountService::bind($s,$native);$s['_merchant_login_outlet']=$m['loginOutlet'];return new StaffSessionIdentity($db,static fn()=>$s,getenv('KIOS_MERCHANT_AUTH_RATE_KEY'));}
function fingerprint(PDO $db):array{$out=[];foreach($db->query('SHOW TABLES')->fetchAll(PDO::FETCH_COLUMN)as $t){$rows=array_map('serialize',$db->query('SELECT * FROM `'.$t.'`')->fetchAll(PDO::FETCH_ASSOC));sort($rows);$out[$t]=hash('sha256',implode("\n",$rows));}ksort($out);return $out;}
$pa=auth($a,$a['username'],$creds['owner_a_password']);$pb=auth($b,$b['username'],$creds['owner_b_password']);$analytics=new OperationalAnalytics($db,$pa);$other=new OperationalAnalytics($db,$pb);$from=gmdate('Y-m-d',time()-86400*6);$to=gmdate('Y-m-d');$load=fn($outlet=null)=>$analytics->load($a['merchant'],$outlet??$a['outlet'],$from,$to);$annex=Identity::generate();
test('Bounded inclusive UTC filters reject invalid dates and SQL payloads',function()use($analytics,$a,$from,$to){foreach([['2026-02-30','2026-03-01'],['2026-01-01','2026-12-31'],['2026-11-20','2026-11-01']]as [$f,$t])deny(fn()=>OperationalAnalytics::period($f,$t));deny(fn()=>$analytics->load($a['merchant'],$a['outlet'],$from,$to,'1 OR 1=1'));});
test('Independent two-merchant and outlet authorization protects metrics and exports',function()use($analytics,$other,$a,$b,$from,$to){deny(fn()=>$analytics->load($b['merchant'],$b['outlet'],$from,$to));deny(fn()=>$analytics->load($a['merchant'],$b['outlet'],$from,$to));deny(fn()=>$other->load($a['merchant'],'all',$from,$to));ok($other->load($b['merchant'],$b['outlet'],$from,$to)['merchant']===$b['merchant']);});
test('Current source service totals reconcile independently without join multiplication',function()use($load,$db,$a,$from,$to){$d=$load();$metrics=[];foreach($d['metrics']as $m)$metrics[$m[1]]=$m[2];[$start,$end]=OperationalAnalytics::period($from,$to);$q=$db->prepare('SELECT COUNT(*) FROM merchant_service_sessions WHERE merchant_id=? AND outlet_id=? AND created_epoch>=? AND created_epoch<?');$q->execute([$a['merchant'],$a['outlet'],$start,min($end,time()+1)]);ok($metrics['Internal services created']===(int)$q->fetchColumn());foreach(['submit'=>'Kitchen submissions','served'=>'Service completions']as $op=>$label){$q=$db->prepare('SELECT DISTINCT service_id FROM merchant_service_events WHERE merchant_id=? AND outlet_id=? AND operation=? AND occurred_epoch>=? AND occurred_epoch<?');$q->execute([$a['merchant'],$a['outlet'],$op,$start,min($end,time()+1)]);ok($metrics[$label]===count($q->fetchAll(PDO::FETCH_COLUMN)));}ok($d['kitchen']!==[]);});
test('Inventory signed movement totals and all-time balances reconcile including reversals',function()use($load,$db,$a,$from,$to){$d=$load();foreach($d['inventory']as $i)ok($i[6]==='MATCH');$byUnit=[];foreach($d['movements']as $v)$byUnit[$v[2]]=($byUnit[$v[2]]??0)+$v[3];[$start,$end]=OperationalAnalytics::period($from,$to);$q=$db->prepare('SELECT i.unit,SUM(v.delta_milli) delta FROM merchant_inventory_movements v JOIN merchant_inventory_items i ON i.merchant_id=v.merchant_id AND i.outlet_id=v.outlet_id AND i.item_id=v.item_id JOIN merchant_inventory_events e ON e.request_id=v.request_id WHERE v.merchant_id=? AND v.outlet_id=? AND e.occurred_epoch>=? AND e.occurred_epoch<? GROUP BY i.unit');$q->execute([$a['merchant'],$a['outlet'],$start,min($end,time()+1)]);foreach($q->fetchAll(PDO::FETCH_ASSOC)as $v)ok(abs($byUnit[$v['unit']]-(int)$v['delta']/1000)<0.0001);ok((bool)array_filter($d['movements'],fn($v)=>str_starts_with($v[1],'reverse:')));});
test('Multiple outlets aggregate only for owner; manager and cashier scope remain restricted',function()use($db,$a,$annex,$load,$from,$to){$db->prepare('INSERT INTO outlets(name,outlet_code,active) VALUES(?,?,1)')->execute(['Synthetic analytics annex','analytics-annex']);$legacy=(int)$db->lastInsertId();$db->prepare('INSERT INTO merchant_outlets(outlet_id,merchant_id,name,active) VALUES(?,?,?,1)')->execute([$annex,$a['merchant'],'=Synthetic CSV outlet']);$db->prepare('INSERT INTO merchant_legacy_outlets(merchant_id,merchant_outlet_id,legacy_outlet_id) VALUES(?,?,?)')->execute([$a['merchant'],$annex,$legacy]);$all=$load('all');ok(count($all['selected'])===2);$single=$load();$sum=fn($d,$label)=>array_sum(array_map(fn($m)=>$m[1]===$label?$m[2]:0,$d['metrics']));ok($sum($all,'Kitchen submissions')===$sum($single,'Kitchen submissions'));$staff=json_decode(file_get_contents('C:/Mapped/Results/m05b-staff.json'),true);$manager=new OperationalAnalytics($db,auth($a,$staff['outlet_administrator']['username'],$staff['outlet_administrator']['password']));ok(count($manager->load($a['merchant'],$a['outlet'],$from,$to)['selected'])===1);deny(fn()=>$manager->load($a['merchant'],'all',$from,$to));deny(fn()=>$manager->load($a['merchant'],$annex,$from,$to));$cashier=new OperationalAnalytics($db,auth($a,$staff['cashier']['username'],$staff['cashier']['password']));deny(fn()=>$cashier->load($a['merchant'],$a['outlet'],$from,$to));});
test('Analytics uses a read-only snapshot and restores session timezone without row mutations',function()use($db,$load){$db->exec("SET time_zone='+05:30'");$before=fingerprint($db);$d=$load();ok($db->query('SELECT @@session.time_zone')->fetchColumn()==='+05:30');ok(fingerprint($db)===$before);ok($d['timezone']==='UTC');$db->exec("SET time_zone='+00:00'");});
test('CSV uses same scoped metrics and neutralizes formula labels without private notes',function()use($load){$d=$load('all');$csv=OperationalAnalytics::csv($d);ok(str_contains($csv,"'=Synthetic CSV outlet"));ok(!str_contains($csv,'password')&&!str_contains($csv,'Hosted no chilli')&&!str_contains($csv,'Browser no chilli'));foreach($d['metrics']as $metric)ok(str_contains($csv,$metric[1]));});
test('Empty historical periods display unavailable timing instead of invented zero averages',function()use($analytics,$a){$d=$analytics->load($a['merchant'],$a['outlet'],'2001-01-01','2001-01-02');ok($d['kitchen']===[]&&$d['reservations']===[]);ok((bool)array_filter($d['export'],fn($r)=>$r[4]==='seconds'&&$r[3]==='Unavailable'));ok($d['inventory']!==[]);$html=\Kios\MerchantOperations\OperationalAnalyticsView::render($d);ok(str_contains($html,'Unavailable')&&str_contains($html,'No eligible records'));});
test('Duplicate synthetic preparation timestamps are excluded from means and flagged',function()use($db,$a,$load){$before=$load();$validBefore=array_sum(array_column($before['kitchen'],7));$invalidBefore=array_sum(array_column($before['kitchen'],9));$q=$db->prepare("INSERT INTO preparation_task_events(outlet_id,order_id,preparation_task_id,from_status,to_status,changed_by) SELECT outlet_id,order_id,preparation_task_id,'preparing','ready','fixture:duplicate-timing' FROM preparation_task_events WHERE outlet_id=? AND to_status='ready' ORDER BY preparation_task_event_id LIMIT 1");$q->execute([$a['loginOutlet']]);ok($q->rowCount()===1);$after=$load();ok(array_sum(array_column($after['kitchen'],7))===$validBefore-1);ok(array_sum(array_column($after['kitchen'],9))===$invalidBefore+1);ok((bool)array_filter($after['quality'],fn($v)=>str_contains($v,'invalid timing pairs')));});
test('Profile representative synthetic ledger history with reconciled live metrics',function()use($db,$pa,$a,$load,&$r){$inv=new Inventory($db,$pa);$item=$inv->load($a['merchant'],$a['outlet'])['items'][0]['item_id'];for($i=0;$i<200;$i++)$inv->act($a['merchant'],$a['outlet'],bin2hex(random_bytes(16)),'receipt',['item'=>$item,'quantity'=>'0.001','reason'=>'Synthetic analytics performance fixture']);$start=hrtime(true);$d=$load();$ms=(hrtime(true)-$start)/1e6;ok($ms<10000);foreach($d['inventory']as $row)ok($row[6]==='MATCH');$r['performance']=['fixture'=>'200 authorized synthetic receipt events plus existing suites','loadMilliseconds'=>$ms,'thresholdMilliseconds'=>10000,'productionScaleBenchmark'=>false];});
file_put_contents($argv[3],json_encode($r,JSON_PRETTY_PRINT));echo json_encode($r);exit($r['failed']?1:0);
